-- Listing expansion, November 2026, batch 3b (issue #523): 4 Taiwanese food listings near TSMC (north Phoenix, Glendale).
-- New rows only (on conflict (slug) do nothing). Category looked up by slug, so the same file runs on dev and production.

begin;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$taiwan-mama-deer-valley-phoenix$lx$, (select id from public.business_categories where slug = $lx$dining$lx$), $lx$Taiwan MaMa (Deer Valley)$lx$, null, $lx$Taiwanese bento, popcorn chicken, braised pork rice and boba tea in north Phoenix's Deer Valley, near TSMC.$lx$, $lx$鳳凰城北部 Deer Valley 的台灣料理與珍奶店，供應便當、鹽酥雞、爌肉飯，鄰近台積電廠區。$lx$, $lx$Taiwan MaMa is a Taiwanese restaurant and bubble tea shop at 822 E Union Hills Dr, D-16, in the Deer Valley area of north Phoenix, which the restaurant calls its flagship store. The menu covers crispy chicken cutlets, popcorn chicken, braised pork belly rice and other bento-style dishes, traditional stir-fries and Taiwanese boba tea. Founder Kate started the business as a cloud kitchen after moving to Phoenix, and Taiwan's Central News Agency reported in December 2025 that it has become a regular gathering place for TSMC engineers and their families. Open 11 a.m. to 9 p.m., closed Mondays, according to its website (checked November 2026).$lx$, $lx$Taiwan MaMa 是位於鳳凰城北部 Deer Valley（822 E Union Hills Dr, D-16）的台灣料理餐廳兼珍珠奶茶店，店家稱這裡為旗艦店。菜單有炸雞排、鹽酥雞、爌肉飯等便當類餐點，以及台式熱炒與珍珠奶茶。創辦人 Kate 來到鳳凰城後從雲端廚房起家；中央社 2025 年 12 月報導，這裡已成為台積電工程師與家人常聚的地方。依官網資訊（2026 年 11 月查核），營業時間為上午 11 點至晚上 9 點，週一公休。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$822 E Union Hills Dr, D-16, Phoenix, AZ 85024$lx$, null, $lx$(623) 204-0919$lx$, null, $lx$https://ustaiwanmama.com/$lx$, array[$lx$English$lx$]::text[], array[$lx$Taiwan MaMa (Deer Valley)$lx$, $lx$Phoenix$lx$, $lx$dining$lx$, $lx$ustaiwanmama.com$lx$, $lx$English$lx$, $lx$Taiwanese food$lx$, $lx$台灣料理 台灣小吃$lx$, $lx$TSMC$lx$, $lx$台積電$lx$, $lx$boba$lx$, $lx$珍珠奶茶$lx$, $lx$便當$lx$, $lx$Deer Valley$lx$]::text[], true, false, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$tofu-king-late-night-phoenix$lx$, (select id from public.business_categories where slug = $lx$dining$lx$), $lx$Tofu King & Late Night$lx$, null, $lx$North Phoenix Taiwanese restaurant known for fresh stinky tofu, with bookable karaoke rooms and catering.$lx$, $lx$鳳凰城北部台灣料理餐廳，招牌現做臭豆腐，另有可預約的卡拉 OK 包廂及外燴服務。$lx$, $lx$Tofu King & Late Night is a Taiwanese restaurant at 2855 W Cactus Rd, Suite 2, in north Phoenix, known for stinky tofu made fresh daily. The menu covers traditional Taiwanese dishes along with seafood boil and handcrafted drinks, and the restaurant has karaoke rooms that can be booked ahead for a night out. It also caters events across Phoenix, from corporate gatherings and weddings to private parties. The website describes its dishes in both English and Chinese (checked November 2026).$lx$, $lx$Tofu King & Late Night 是位於鳳凰城北部 2855 W Cactus Rd, Suite 2 的台灣料理餐廳，招牌是每天新鮮現做的臭豆腐。菜單有傳統台灣菜，也有海鮮鍋（seafood boil）及手作飲品；店內設有可預約的卡拉 OK 包廂，適合夜間聚會。也承辦鳳凰城各地的公司活動、婚禮及私人派對外燴。官網以中英文介紹菜色（2026 年 11 月查核）。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$2855 W Cactus Rd, Suite 2, Phoenix, AZ 85029$lx$, null, $lx$(623) 692-2816$lx$, null, $lx$https://www.tofukingphoenix.com/$lx$, array[$lx$English$lx$]::text[], array[$lx$Tofu King & Late Night$lx$, $lx$Phoenix$lx$, $lx$dining$lx$, $lx$tofukingphoenix.com$lx$, $lx$English$lx$, $lx$Taiwanese food$lx$, $lx$台灣料理 台灣小吃$lx$, $lx$TSMC$lx$, $lx$台積電$lx$, $lx$stinky tofu$lx$, $lx$臭豆腐$lx$, $lx$karaoke$lx$, $lx$卡拉OK$lx$]::text[], true, false, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$cactiflower-phoenix$lx$, (select id from public.business_categories where slug = $lx$dining$lx$), $lx$CactiFlower$lx$, null, $lx$Small north Phoenix takeout spot for Taiwanese boxed meals such as lu rou fan, opened in 2025.$lx$, $lx$鳳凰城北部的台灣盒餐小店，供應滷肉飯等台灣味，2025 年開幕。$lx$, $lx$CactiFlower is a small Taiwanese restaurant at 15414 N 19th Ave, Suite O, in north Phoenix, near 19th Avenue and Greenway Road. It serves Taiwanese food in a box, from street food to slow-braised dishes. Owner Elizabeth Heubusch, who spent many childhood years in Taiwan, opened it in July 2025 to give the growing Taiwanese community a taste of home; KJZZ and Phoenix Magazine have both covered it, including its lu rou fan (braised pork over rice). Open Tuesday to Saturday, 1 to 7 p.m., according to its website (checked November 2026).$lx$, $lx$CactiFlower 是位於鳳凰城北部 15414 N 19th Ave, Suite O（19th Ave 與 Greenway Rd 附近）的小型台灣料理店，以盒餐供應台灣味，官網形容「從街頭小吃到細燉館子菜，都能裝進這個盒子裡」。店主 Elizabeth Heubusch 童年多在台灣度過，2025 年 7 月開店，希望讓日漸增加的台灣社群吃到家鄉味；KJZZ 電台及 Phoenix Magazine 都曾報導，包括滷肉飯。依官網資訊（2026 年 11 月查核），營業時間為週二至週六下午 1 點至 7 點。$lx$, $lx$Phoenix$lx$, $lx$Greater Phoenix$lx$, $lx$15414 N 19th Ave, Suite O, Phoenix, AZ 85023$lx$, null, $lx$(562) 205-8613$lx$, null, $lx$https://www.cactiflower.com/$lx$, array[$lx$English$lx$]::text[], array[$lx$CactiFlower$lx$, $lx$Phoenix$lx$, $lx$dining$lx$, $lx$cactiflower.com$lx$, $lx$English$lx$, $lx$Taiwanese food$lx$, $lx$台灣料理 台灣小吃$lx$, $lx$TSMC$lx$, $lx$台積電$lx$, $lx$lu rou fan$lx$, $lx$滷肉飯$lx$, $lx$bento$lx$, $lx$便當$lx$]::text[], true, false, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
on conflict (slug) do nothing;

insert into public.businesses (slug, category_id, name_en, name_zh_tw, short_description_en, short_description_zh_tw, description_en, description_zh_tw, city, region, address, service_area_text, phone, email, website, languages, search_aliases, verified, bilingual, newcomer_friendly, sponsored, featured, status, verification_state, last_updated)
values ($lx$85c-bakery-cafe-arrowhead-glendale$lx$, (select id from public.business_categories where slug = $lx$dining$lx$), $lx$85°C Bakery Cafe (Arrowhead Ranch)$lx$, $lx$85度C$lx$, $lx$Taiwanese bakery chain's Glendale store with breads, cakes, sea salt coffee and a drive-thru.$lx$, $lx$台灣烘焙連鎖 85度C 的格倫代爾門市，有麵包、蛋糕及海鹽咖啡，設有得來速。$lx$, $lx$85°C Bakery Cafe's Arrowhead Ranch store at 7280 W Bell Rd in Glendale is a West Valley location of the Taiwanese bakery chain, which opened its first shop in Taiwan in 2004. It sells breads, pastries and cakes along with tea and coffee drinks such as its sea salt coffee, and the Arizona Republic reported in early 2025 that the store has a drive-thru. The address is from the chain's official store finder (checked November 2026); check there for current hours.$lx$, $lx$85度C（85°C Bakery Cafe）Arrowhead Ranch 店位於格倫代爾 7280 W Bell Rd，是這家台灣烘焙連鎖在西谷的門市；85度C 於 2004 年在台灣開出第一家店。店內販售麵包、糕點與蛋糕，以及海鹽咖啡等茶飲與咖啡；《亞利桑那共和報》2025 年初報導這家店設有得來速。地址依品牌官方門市查詢（2026 年 11 月查核），最新營業時間請以官網為準。$lx$, $lx$Glendale$lx$, $lx$Greater Phoenix$lx$, $lx$7280 W Bell Rd, Glendale, AZ 85308$lx$, null, null, null, $lx$https://www.85cbakerycafe.com/$lx$, array[$lx$English$lx$]::text[], array[$lx$85°C Bakery Cafe (Arrowhead Ranch)$lx$, $lx$85度C$lx$, $lx$Glendale$lx$, $lx$dining$lx$, $lx$85cbakerycafe.com$lx$, $lx$English$lx$, $lx$Taiwanese bakery$lx$, $lx$台灣麵包 蛋糕$lx$, $lx$bakery$lx$, $lx$麵包店$lx$, $lx$sea salt coffee$lx$, $lx$海鹽咖啡$lx$, $lx$85 Degrees$lx$, $lx$Arrowhead$lx$]::text[], true, false, false, false, false, $lx$live$lx$, $lx$editor_verified$lx$, now())
